(6852259, 1030736, 49954, '<td valign="top">Very abstract, but oddly appealing</td>', 'Very abstract, but oddly appealing', '2012-08-30 08:55:39.000000', NULL, 1),
(6852260, 1030816, 49954, '<td valign="top">Nice work and processing... sometimes these colorforms images look cheesy, but I like this one... the look on the cat''s face is priceless.</td>', 'Nice work and processing... sometimes these colorforms images look cheesy, but I like this one... the look on the cat''s face is priceless.', '2012-08-30 08:56:06.000000', NULL, 1),
