(6852265, 1030776, 49954, '<td valign="top">"Babes in the Wood" is the rhyme, but close enough...</td>', '"Babes in the Wood" is the rhyme, but close enough...', '2012-08-30 09:01:01.000000', NULL, 1),
(6852267, 1030854, 49954, '<td valign="top">Great image overall... but not getting the theme...  Jack Sprat?  Jack be Nimble?  Jack and the Beanstalk?</td>', 'Great image overall... but not getting the theme...  Jack Sprat?  Jack be Nimble?  Jack and the Beanstalk?', '2012-08-30 09:01:47.000000', NULL, 1),
(6852268, 1030855, 49954, '<td valign="top">Cute expressions and story.  More light (and thus clearer picture) would have helped.  The background also does nothing expect make it look like actors on a stage.  Closer crop of the two subjects might have been stronger...</td>', 'Cute expressions and story.  More light (and thus clearer picture) would have helped.  The background also does nothing expect make it look like actors on a stage.  Closer crop of the two subjects might have been stronger...', '2012-08-30 09:02:40.000000', NULL, 1),
(6852269, 1030813, 49954, '<td valign="top">Great photo opp... downside is she''s too dark, except for her thigh.  Nice background.</td>', 'Great photo opp... downside is she''s too dark, except for her thigh.  Nice background.', '2012-08-30 09:03:19.000000', NULL, 1),
(6852271, 1030830, 49954, '<td valign="top">Cute effort and editing.  I''d planned to do Humpty too, so for both our sakes I''m glad I didn''t as people like to punish that here...</td>', 'Cute effort and editing.  I''d planned to do Humpty too, so for both our sakes I''m glad I didn''t as people like to punish that here...', '2012-08-30 09:03:53.000000', NULL, 1),
(6852272, 1030612, 49954, '<td valign="top">Creepy and eerie... well done.  But Lizzie Borden isn''t a fairy tale (a true story) nor really a nursery rhyme, even though there is a rhyme about the killings.</td>', 'Creepy and eerie... well done.  But Lizzie Borden isn''t a fairy tale (a true story) nor really a nursery rhyme, even though there is a rhyme about the killings.', '2012-08-30 09:03:56.000000', NULL, 1),
(6852273, 1030729, 49954, '<td valign="top">Nice abstract.  Would like to see a little more tight (lose the bottom left corner) to make it more abstract.</td>', 'Nice abstract.  Would like to see a little more tight (lose the bottom left corner) to make it more abstract.', '2012-08-30 09:04:37.000000', NULL, 1),
