(6852275, 1030305, 49954, '<td valign="top">Interesting processing choice... not sure that it adds anything to the overall effect however.</td>', 'Interesting processing choice... not sure that it adds anything to the overall effect however.', '2012-08-30 09:06:39.000000', NULL, 1),
